import { presenceUserKey } from "../../../src/shared/presence-user.ts";
import type { GatewayBrowserClient } from "../api/gateway.ts";
import { selectApplicationSession } from "../app/agent-selection.ts";
import type { ApplicationGateway } from "../app/gateway.ts";
import { projectOnlinePresenceViewers, profilePresenceViewer } from "../lib/presence-users.ts";
import { profileDirectory } from "../lib/profile-directory.ts";
import { listen } from "../lib/reactive/listener.ts";
import { runSessionNavigationIntent } from "../lib/sessions/navigation-handoff.ts";
import { resolveSessionPreferredFace } from "../lib/sessions/route-navigation.ts";
import {
  isUiGlobalScopeConfigured,
  resolveUiConfiguredMainKey,
  resolveUiDefaultAgentId,
} from "../lib/sessions/session-key.ts";
import type { AppSidebarSessionNavigationElement } from "./app-sidebar-session-navigation.ts";
import {
  hovercardBootstrapIntentActive,
  remainingHovercardOpenDelay,
} from "./lazy-hovercard-registration.ts";
import { updatePersonActivityCard } from "./person-activity-card.tsx";
import { observePersonActivityData } from "./person-activity-data.ts";
import { personActivityRouting } from "./person-activity-link.ts";
import { createPortaledHovercard, createPortaledHovercardOwner } from "./portaled-hovercard.ts";

let nextCardId = 0;

export class SidebarPeopleRuntime {
  private active: {
    id: string;
    row: HTMLElement;
    trigger: HTMLElement;
    scope: string;
    gateway: ApplicationGateway;
    client: GatewayBrowserClient | null;
  } | null = null;
  private readonly portal = createPortaledHovercardOwner(() => this.close(), 100);
  private readonly observer = new MutationObserver(() => this.sync());
  private lastOpenAt = -Infinity;
  private activity: ReturnType<typeof observePersonActivityData> | undefined;
  private readonly stopGateway: (() => void) | undefined;
  private stopListeners: Array<() => void> = [];

  constructor(private readonly host: AppSidebarSessionNavigationElement) {
    // Retire connection-bound cards without waiting for a sidebar repaint.
    this.stopGateway = host.sessionDataContext?.gateway.subscribe(() => {
      if (!this.isCurrent()) {
        this.close();
      }
    });
  }

  private scope(): string {
    return JSON.stringify([
      this.host.activeRouteId,
      this.host.sessionKey,
      this.host.sessionDataContext?.gateway.connectionRevision,
    ]);
  }

  handleEvent(event: Event, bootstrapStartedAt?: number): void {
    const row =
      event.target instanceof Element
        ? event.target.closest<HTMLElement>("[data-person-card]")
        : null;
    if (event.type === "keydown" && event instanceof KeyboardEvent) {
      if (event.key === "Tab") {
        this.portal.handleTriggerKeyDown(event);
      }
      return;
    }
    if (!row) {
      return;
    }
    // Import completion must not replay a hover or focus that already moved away.
    if (
      bootstrapStartedAt !== undefined &&
      event.type !== "click" &&
      !hovercardBootstrapIntentActive(row, event.type === "focusin" ? "focus" : "pointer", true)
    ) {
      return;
    }
    if (event.type === "click") {
      if (this.active?.row === row && this.portal.explicitHold) {
        this.close();
        return;
      }
      this.activate(row, 0);
      this.portal.explicitHold = true;
      this.show();
    } else if (event.type === "pointerover" && event instanceof PointerEvent) {
      if (event.pointerType === "touch" || !globalThis.matchMedia?.("(hover: hover)").matches) {
        return;
      }
      if (this.portal.explicitHold && this.active?.row !== row) {
        return;
      }
      const enter = (startedAt = performance.now()) => {
        const delay = this.portal.card || performance.now() - this.lastOpenAt < 300 ? 80 : 450;
        this.activate(row, remainingHovercardOpenDelay(startedAt, delay));
        this.portal.pointerInside = true;
        this.portal.clearClose();
      };
      // Rows crossed on the way to the open card must not take it over.
      if (this.active?.row !== row && this.portal.deferPointerSwitch(event, row, enter)) {
        return;
      }
      enter(bootstrapStartedAt);
    } else if (
      event.type === "pointerout" &&
      event instanceof PointerEvent &&
      this.active?.row === row
    ) {
      if (event.relatedTarget instanceof Node && row.contains(event.relatedTarget)) {
        return;
      }
      this.portal.schedulePointerExit(event);
    } else if (event.type === "focusin" && !this.portal.restoringFocus) {
      // Pointer focus must not put a card over a navigation link before its click.
      if (event.target instanceof HTMLAnchorElement && !event.target.matches(":focus-visible")) {
        return;
      }
      this.activate(row, 0);
      this.portal.focusInside = true;
      this.portal.clearClose();
      this.show();
    } else if (
      event.type === "focusout" &&
      event instanceof FocusEvent &&
      this.active?.row === row
    ) {
      if (event.relatedTarget instanceof Node && row.contains(event.relatedTarget)) {
        return;
      }
      this.portal.focusInside = false;
      this.portal.scheduleClose();
    }
  }

  private activate(row: HTMLElement, delay: number): void {
    const trigger = this.host.personCardTriggers.get(row) ?? row;
    const id = trigger.dataset.personCardKey;
    if (!id || !this.host.connected) {
      return;
    }
    if (this.active?.id === id && this.active.row === row) {
      return;
    }
    this.close();
    const gateway = this.host.sessionDataContext?.gateway;
    if (!gateway || gateway.snapshot.phase !== "connected") {
      return;
    }
    this.active = {
      id,
      row,
      trigger,
      scope: this.scope(),
      gateway,
      client: gateway.snapshot.client,
    };
    this.portal.markTrigger(trigger);
    this.observer.observe(this.host.hostElement, { childList: true, subtree: true });
    this.stopListeners = [
      listen(document, "pointerdown", this.outsideInteraction, true),
      listen(document, "focusin", this.outsideInteraction, true),
      listen(document, "keydown", this.outsideKey, true),
    ];
    this.portal.scheduleOpen(delay, () => {
      if (this.portal.held) {
        this.show();
      }
    });
  }

  private isCurrent(): boolean {
    const active = this.active;
    const gateway = this.host.sessionDataContext?.gateway;
    return Boolean(
      active &&
      this.host.isConnected &&
      this.host.connected &&
      gateway?.snapshot.phase === "connected" &&
      active.gateway === gateway &&
      active.client === gateway.snapshot.client &&
      active.scope === this.scope() &&
      this.host.hostElement.contains(active.row),
    );
  }

  sync(): void {
    if (!this.isCurrent()) {
      this.close();
    } else if (this.portal.card) {
      this.show();
    }
  }

  private show(): void {
    const active = this.active;
    const context = this.host.sessionDataContext;
    if (!active || !context || !this.isCurrent()) {
      this.close();
      return;
    }
    const data = this.host.sessionData;
    let user = projectOnlinePresenceViewers(data.presencePayload).find(
      (person) => presenceUserKey(person) === active.id,
    );
    if (!user && active.id.startsWith("profile:")) {
      const profileId = active.id.slice("profile:".length);
      const profile = profileDirectory(context.gateway).get(profileId);
      if (profile) {
        user = profilePresenceViewer(profile);
      }
      const actor = [data.sessionsResult, ...Object.values(data.sessionResultsByAgent)]
        .flatMap((result) => result?.sessions ?? [])
        .flatMap((row) => [row.owner?.actor, row.createdActor])
        .find(
          (candidate) =>
            candidate?.identity?.type === "profile" && candidate.identity.id === profileId,
        );
      if (!user && actor) {
        user = {
          id: profileId,
          identity: { type: "profile", id: profileId },
          name: actor.label,
          avatarUrl: actor.avatarUrl,
          watchedSessions: [],
          entries: [],
        };
      }
    }
    if (!user) {
      this.close();
      return;
    }
    const activity = (this.activity ??= observePersonActivityData(context, () => this.sync()));
    const defaults = {
      agentsList: context.agents.state.agentsList,
      hello: context.gateway.snapshot.hello,
    };
    const existing = this.portal.card;
    const card =
      existing ??
      createPortaledHovercard(
        `openclaw-person-activity-${++nextCardId}`,
        "session-progress-hovercard person-activity-hovercard",
      );
    this.portal.renderContents(card, () =>
      updatePersonActivityCard(
        card,
        {
          user,
          sessionData: activity.data,
          watchAgentId: resolveUiDefaultAgentId(defaults),
          mainKey: resolveUiConfiguredMainKey(defaults),
          globalScope: isUiGlobalScopeConfigured(defaults),
          routing: personActivityRouting(
            {
              basePath: this.host.basePath,
              navigate: (route, options) => this.host.onNavigate?.(route, options),
            },
            () => this.close(),
          ),
          openSession: (row, agentId, options) => {
            const face = resolveSessionPreferredFace(row);
            this.close();
            runSessionNavigationIntent(this.host, {
              agentId,
              face,
              sessionKey: row.key,
              commit: () => {
                if (
                  this.host.sessionDataContext?.gateway !== active.gateway ||
                  context.gateway.snapshot.client !== active.client ||
                  context.gateway.snapshot.phase !== "connected" ||
                  active.scope !== this.scope()
                ) {
                  return false;
                }
                this.host.prepareSessionNavigation(row.key, options.pathname);
                this.host.onNavigate?.(face, options);
                selectApplicationSession({
                  selection: context.agentSelection,
                  gateway: context.gateway,
                  sessionKey: row.key,
                  agentId,
                });
                return true;
              },
            });
          },
        },
        () => this.portal.position(),
      ),
    );
    if (existing) {
      this.portal.position();
      return;
    }
    this.lastOpenAt = performance.now();
    this.stopListeners.push(listen(card, "pointerleave", this.portal.handleCardPointerLeave));
    this.portal.mount(active.row, card, "horizontal", true, () => updatePersonActivityCard(card));
  }

  private readonly outsideInteraction = (event: Event) => {
    if (
      event.target instanceof Node &&
      !this.active?.row.contains(event.target) &&
      !this.portal.card?.contains(event.target)
    ) {
      this.close();
    }
  };

  private readonly outsideKey = (event: KeyboardEvent) => {
    if (event.key === "Escape") {
      // The card owns this Escape, not the modal navigation drawer beneath it.
      event.preventDefault();
      event.stopPropagation();
      if (this.portal.card?.contains(document.activeElement)) {
        this.portal.returnFocus(this.active?.trigger ?? null);
        this.portal.focusInside = document.activeElement === this.active?.trigger;
      }
      this.close();
    }
  };

  private close(): void {
    if (this.portal.card) {
      this.lastOpenAt = performance.now();
    }
    this.activity?.dispose();
    this.activity = undefined;
    this.observer.disconnect();
    this.stopListeners.forEach((stop) => stop());
    this.stopListeners = [];
    this.portal.reset();
    this.active?.trigger.setAttribute("aria-haspopup", "dialog");
    this.active?.trigger.setAttribute("aria-expanded", "false");
    this.active = null;
  }

  dismiss(): boolean {
    const hadCard = this.active !== null;
    this.close();
    return hadCard;
  }

  dispose(): void {
    this.close();
    this.stopGateway?.();
  }
}
